<?php
require_once "config.php"; require_login(); $uid=(int)$_SESSION["user_id"]; $stmt=$pdo->prepare("SELECT * FROM users WHERE id=?");$stmt->execute([$uid]);$user=$stmt->fetch();$error="";
if($_SERVER["REQUEST_METHOD"]==="POST"){$name=trim($_POST["name"]??"");$email=trim($_POST["email"]??"");if(!$name||!filter_var($email,FILTER_VALIDATE_EMAIL))$error="Enter a valid name and email.";else{$check=$pdo->prepare("SELECT id FROM users WHERE email=? AND id<>?");$check->execute([$email,$uid]);if($check->fetch())$error="This email is already used by another account.";else{$up=$pdo->prepare("UPDATE users SET name=?,email=? WHERE id=?");$up->execute([$name,$email,$uid]);$_SESSION["name"]=$name;flash("Profile updated successfully.");header("Location: profile.php");exit;}}}
app_header("My Profile"); ?>
<div class="welcome"><div><h1>My Profile</h1><p>View and update your account information.</p></div></div><div class="panel profile-panel"><div class="profile-heading"><div class="avatar"><?=e(strtoupper(substr($user["name"],0,1)))?></div><div><h2><?=e($user["name"])?></h2><span class="pill"><?=e(ucfirst($user["role"]))?></span></div></div><?php if($error): ?><div class="alert error"><?=e($error)?></div><?php endif; ?><form method="post" class="profile-form"><div class="two-col"><label>Full Name<input name="name" value="<?=e($user["name"])?>" required></label><label>Email<input type="email" name="email" value="<?=e($user["email"])?>" required></label><label>Username<input value="<?=e($user["username"])?>" disabled></label><label>Role<input value="<?=e(ucfirst($user["role"]))?>" disabled></label><?php if($user["role"]==="student"): ?><label>Student ID<input value="<?=e($user["student_code"])?>" disabled></label><label>Semester<input value="<?=e($user["semester"])?>" disabled></label><?php elseif($user["role"]==="faculty"): ?><label>Faculty ID<input value="<?=e($user["faculty_code"])?>" disabled></label><label>Designation<input value="<?=e($user["designation"])?>" disabled></label><?php endif; ?><label>Department<input value="<?=e($user["department"])?>" disabled></label></div><button class="btn primary" type="submit">Update Profile</button></form></div>
<?php app_footer(); ?>
